linux.post_install:
# Folders the server writes its log into.
mkdir -p logs/server

unpack() {
  if unzip -tq "$1" > /dev/null 2>&1; then unzip -oq "$1"; else tar -xf "$1"; fi
  rm -f "$1"
}
github_asset() {
  curl -fsSL "https://api.github.com/repos/$1/releases/latest" | python3 -c '
import json, sys
wanted = sys.argv[1]
for asset in json.load(sys.stdin)["assets"]:
    if wanted in asset["name"]:
        print(asset["browser_download_url"])
        break
' "$2"
}
url="$(github_asset rollerozxa/luantiserver "x86_64.tar.gz")"
curl -fL --retry 3 -o gse-download "$url"
unpack gse-download
